{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Living systematic review and network meta-analysis.",
      "reason": "The title explicitly includes the phrase \"systematic review\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Drug treatments for covid-19: living systematic review and network meta-analysis",
      "reason": "The title identifies the population (\"covid-19\") and the intervention (\"Drug treatments\")."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Living systematic review and network meta-analysis.",
      "reason": "The title includes \"living\" and \"network meta-analysis,\" which are relevant supplementary information regarding the review status and analysis method."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Despite global efforts to identify effective interventions for the prevention and treatment of covid-19, which have resulted in approximately 3000 trials completed or underway, 2 evidence for effective treatment remains limited. Summarising the rapidly growing evidence base has been a challenge.",
      "reason": "The text describes the current state of knowledge (many trials underway) and the uncertainty/challenge (evidence for effective treatment remains limited and summarizing it is a challenge)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The ability of a living network meta-analysis to present a complete, broad, and updated view of the evidence makes it the best type of evidence synthesis to inform the development of practice recommendations.",
      "reason": "The text explains the need for the review, specifically highlighting that a living network meta-analysis is the best approach to inform practice recommendations in the context of rapidly changing evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "To date, we are aware of two other similar efforts to ours. 42 43 Our intention is different in that the results fully inform clinical decision makingfor the associated living guidance. 6 Wealsoinclude a more comprehensive search for the evidence and several differences in analytical methods, which we believe are best suited for this evidence.",
      "reason": "The authors acknowledge similar existing reviews and explain the need for their specific review by highlighting differences in intention, search comprehensiveness, and analytical methods."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "Mounting evidence suggests that antivirals (such as molnupiravir and nirmatrelvir) are most effective in the early stages of covid-19 when patients have non-severe disease, whereas anti-inflammatories (such as corticosteroids) seem to be most effective in the later disease stages.",
      "reason": "The text briefly describes the proposed mechanism of action/effectiveness timing for the interventions (antivirals vs anti-inflammatories) in the context of the disease stages."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review focuses on drug treatments for COVID-19, which are not described as complex interventions requiring a logic model in this context."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "To compare the effects of treatments for coronavirus disease 2019 (covid-19).",
      "reason": "The objective of the review is explicitly stated in the abstract."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Randomised clinical trials in which people with suspected, probable, or confirmed covid-19 were randomised to drug treatment or to standard care or placebo.",
      "reason": "The review defines the population (people with suspected, probable, or confirmed covid-19), the intervention (drug treatment), and the comparator (standard care or placebo), which constitutes a PICO framework for the planned comparisons."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Weincluded randomised clinical trials in people with suspected, probable, or confirmed covid-19 that compared drugs for treatment against one another or against no intervention, placebo, or standard care. ... No restrictions were applied based on severity of illness or setting, and we included trials of Chinese medicines if the drug comprised one or more specific molecules with a defined molecular weight dosing. Weexcluded randomised trials evaluating vaccination, blood products and antibody-based antiviral therapies (such as virus-specific monoclonal antibodies), nutrition, traditional Chinese herbal or alternative medicines that include more than one molecule or a molecule without specific molecular weighted dosing, and non-drugsupportive care interventions.",
      "reason": "The manuscript specifies the study design (randomised clinical trials), population (suspected, probable, or confirmed covid-19), and interventions (drugs for treatment vs. no intervention/placebo/standard care), as well as specific exclusions."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "We included trials regardless of publication status (peer reviewed, in press, or preprint) or language.",
      "reason": "The manuscript explicitly states that there were no restrictions on language or publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_26",
      "quote": "Several trials could not be included in the analysis because both arms would have been classified within the same treatment node, they evaluated different durations or doses of the same drug, had insufficient data, or reported no outcomes of interest.",
      "reason": "The text distinguishes between exclusion due to study design/data issues (insufficient data) and exclusion due to reporting (reported no outcomes of interest)."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "For each outcome, interventions were classified in groups from the most to the least beneficial or harmful following GRADE guidance.",
      "reason": "The manuscript describes that interventions were classified into groups for the synthesis (network meta-analysis) based on GRADE guidance."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "For that reason, we decided to report evidence on treatments for which at least 100 people were randomised or for which there were at least 20 events.",
      "reason": "The authors provide a rationale for restricting the analysis to treatments with at least 100 people randomised or 20 events, citing the need to avoid sparse data issues in network meta-analysis."
    }
  ],
  "confidence": 100
}

